def handle(app, svc):
    resp = svc.apply(app)
    outcome = resp["result"]["outcome"]
    credit_limit = int(resp["result"].get("credit_limit", 0) or 0)

    # Network referral rule: self_employed applicants requesting above
    # 6000 must go to manual review instead of being issued. A decline
    # stays a decline.
    if (app.get("employment") == "self_employed"
            and int(app.get("requested_limit", 0) or 0) > 6000
            and outcome == "approved"):
        outcome = "manual_review"

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    # manual_review -> queue for manual review, do not decline
    return {"action": "queue_review", "limit": 0}
